import { analyzePacket, buildHandoff } from './engine.mjs';

export const TRANSFER_KEY = 'drawing-desk:transfer:v1';
const RECEIPT_PREFIX = 'drawing-desk:estimating-inbox:v1:';
export const MAX_FILE_SIZE = 128 * 1024;

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// Walk the shape generated by the review engine, including array order. JSON
// object key order may change when a file passes through another application.
function matchesDocument(actual, expected) {
  if (actual === expected) return true;
  if (Array.isArray(expected)) {
    return Array.isArray(actual) && actual.length === expected.length
      && expected.every((item, i) => matchesDocument(actual[i], item));
  }
  if (!isRecord(actual) || !isRecord(expected)) return false;
  const keys = Object.keys(expected);
  return Object.keys(actual).length === keys.length
    && keys.every(key => Object.hasOwn(actual, key) && matchesDocument(actual[key], expected[key]));
}

export function parseHandoff(text) {
  if (typeof text !== 'string' || text.length > MAX_FILE_SIZE) {
    throw new Error('Choose a Drawing Desk JSON export smaller than 128 KiB.');
  }
  try {
    return JSON.parse(text.replace(/^\uFEFF/, ''));
  } catch {
    throw new Error('This file could not be read as JSON. Choose a handoff downloaded from the workspace.');
  }
}

export function verifyHandoff(document, library) {
  if (!isRecord(document) || document.schema !== 'drawing-desk/handoff' || document.schemaVersion !== 1) {
    throw new Error('This inbox accepts Drawing Desk version 1 handoffs. Choose a JSON handoff from the workspace.');
  }
  if (document.status === 'held' || document.documentType === 'clarification-draft') {
    throw new Error('This is a clarification draft. Resolve the outstanding findings in the workspace before handing it to estimating.');
  }
  if (document.status !== 'ready' || document.documentType !== 'estimating-handoff') {
    throw new Error('The document has an unrecognised handoff status. Export it again from the workspace.');
  }
  const fixture = library.fixtures.find(row => row.id === document.packetId);
  if (!fixture) throw new Error('The packet is outside the inbox’s sample library.');
  const observation = library.observations[fixture.id];
  if (!observation || typeof observation.text !== 'string') throw new Error('This sample’s verified OCR record is unavailable.');
  if (!Array.isArray(document.decisions) || document.decisions.length > 100) {
    throw new Error('The review history is missing or invalid. Export the original handoff again.');
  }
  const review = analyzePacket(fixture, observation.text, library.clauses, document.decisions);
  if (review.ignoredDecisions) throw new Error('The review history cannot be replayed against this sample’s evidence.');
  if (!review.handoffAllowed) throw new Error('This sample still has unresolved findings when its decisions are replayed.');
  const expected = buildHandoff(review);
  if (!matchesDocument(document, expected)) {
    throw new Error('The handoff differs from the verified sample record. Check the evidence and export again using the supplied scan reading.');
  }
  return expected;
}

function readReceipt(storage, fixture, library) {
  const raw = storage.getItem(RECEIPT_PREFIX + fixture.id);
  if (raw === null) return null;
  try {
    const value = JSON.parse(raw);
    if (!isRecord(value) || typeof value.receivedAt !== 'string' ||
        new Date(value.receivedAt).toISOString() !== value.receivedAt ||
        value.handoff?.packetId !== fixture.id) return null;
    return { receivedAt: value.receivedAt, handoff: verifyHandoff(value.handoff, library) };
  } catch {
    return null;
  }
}

export function listReceipts(storage, library) {
  return library.fixtures.map(row => readReceipt(storage, row, library))
    .filter(Boolean).sort((a, b) => b.receivedAt.localeCompare(a.receivedAt));
}

export function receiveHandoff(document, library, storage, now = () => new Date()) {
  const handoff = verifyHandoff(document, library);
  const fixture = library.fixtures.find(row => row.id === handoff.packetId);
  const previous = readReceipt(storage, fixture, library);
  if (previous) return { duplicate: true, receipt: previous };

  const receipt = { receivedAt: now().toISOString(), handoff };
  storage.setItem(RECEIPT_PREFIX + fixture.id, JSON.stringify(receipt));
  return { duplicate: false, receipt };
}
